function validate([num]) {
  if (typeof num !== 'string' || num.length < 1 || num.length > 100000) return 'num needs 1 to 10^5 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only digits.';
  for (let a = 0, b = num.length - 1; a < b; a++, b--) if (num[a] !== num[b]) return 'num must be a palindrome.';
  return null;
}

