function nextPalindrome(num) {
  const n = num.length;
  const half = num.slice(0, Math.floor(n / 2)).split('');
  let i = half.length - 2;
  while (i >= 0 && half[i] >= half[i + 1]) {
    i--;
  }
  if (i < 0) {
    return '';
  }
  let j = half.length - 1;
  while (half[j] <= half[i]) {
    j--;
  }
  [half[i], half[j]] = [half[j], half[i]];
  let left = i + 1;
  let right = half.length - 1;
  while (left < right) {
    [half[left], half[right]] = [half[right], half[left]];
    left++;
    right--;
  }
  const front = half.join('');
  const middle = n % 2 === 1 ? num[Math.floor(n / 2)] : '';
  return front + middle + half.reverse().join('');
}

