function nextPalindrome(num) {
  // Build every distinct arrangement of the digits and keep the smallest palindrome above num.
  const n = num.length;
  const count = new Array(10).fill(0);
  for (const ch of num) count[Number(ch)]++;
  let best = null;
  const digits = [];
  const build = () => {
    if (digits.length === n) {
      const s = digits.join('');
      if (s > num && s === s.split('').reverse().join('') && (best === null || s < best)) best = s;
      return;
    }
    for (let d = 0; d < 10; d++) {
      if (count[d] === 0) continue;
      count[d]--;
      digits.push(d);
      build();
      digits.pop();
      count[d]++;
    }
  };
  build();
  return best === null ? '' : best;
}

