function generate(rand, size) {
  const n = size === 'large' ? 9990 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 8);
  const span = rand() < 0.5 ? 3 : 10;
  const halfLength = Math.floor(n / 2);
  const half = [];
  for (let k = 0; k < halfLength; k++) half.push(Math.floor(rand() * span));
  if (halfLength > 0 && half[0] === 0) half[0] = 1 + Math.floor(rand() * 9);
  // Sometimes make the half non-increasing so that no larger palindrome exists.
  if (rand() < 0.25) half.sort((a, b) => b - a);
  const middle = n % 2 === 1 ? String(halfLength === 0 ? 1 + Math.floor(rand() * 9) : Math.floor(rand() * 10)) : '';
  const front = half.join('');
  return [front + middle + half.slice().reverse().join('')];
}
